class ElementNotFound(Exception):
    """Exception for wrong element reference"""


class ManagedObjectNotFound(ElementNotFound):
    """Exception for wrong managed object reference"""


class ScfCannotBeCreated(Exception):
    """Exception raised while instantiating SCF model"""


class ElementTypeNotSuitable(Exception):
    """The element object is of not suitable type"""


class AttributeSetterNotSupported(Exception):
    """If user wants to set object attribute using Python set attribute syntax"""
